import { readFile, writeFile } from "node:fs/promises";

const root = new URL("../../", import.meta.url);
const check = process.argv.includes("--check");
const header =
  "// Generated by pnpm generate:release-metadata; edit the owning package.json.\n";
const hosted = await readManifest("packages/mcp/package.json");
const worker = await readManifest("packages/local-worker/package.json");
const outputs = new Map([
  [
    "packages/mcp/src/shared/mcpIdentity.constants.ts",
    `${header}export const CAD_MCP_IDENTITY = Object.freeze({\n  name: ${JSON.stringify(hosted.mcpServerName)},\n  version: ${JSON.stringify(hosted.version)},\n});\n`,
  ],
  [
    "packages/contracts/src/domains/worker/workerRelease.constants.ts",
    `${header}export const LOCAL_WORKER_PACKAGE_VERSION = ${JSON.stringify(worker.version)};\nexport const LOCAL_WORKER_MCP_NAME = ${JSON.stringify(worker.mcpServerName)};\n`,
  ],
]);
for (const [path, expected] of outputs) {
  const url = new URL(path, root);
  const actual = await readFile(url, "utf8").catch((error) => {
    if (error.code === "ENOENT") return undefined;
    throw error;
  });
  if (actual === expected) continue;
  if (check)
    throw new Error(`${path} is stale; run pnpm generate:release-metadata.`);
  await writeFile(url, expected);
}

async function readManifest(path) {
  const manifest = JSON.parse(await readFile(new URL(path, root), "utf8"));
  for (const field of ["mcpServerName", "version"]) {
    if (typeof manifest[field] !== "string" || !manifest[field].trim())
      throw new Error(`${path} must define ${field}.`);
  }
  return manifest;
}
